-- 仅用于隔离测试的原表子集，绝不由应用初始化生产库。
CREATE TABLE TSS_BCOMP_CONF_NEW (BCOMP_INDEX BIGINT PRIMARY KEY, BCOMP_NAME VARCHAR(100), BCOMP_TYPE VARCHAR(1), BCOMP_MODULE VARCHAR(100), BCOMP_MEMO VARCHAR(500), BCOMP_RANGE VARCHAR(100), BCOMP_TIME_NODE VARCHAR(20), BCOMP_STATE VARCHAR(20), BCOMP_PARTITION_NUM INT, BCOMP_DATE_MODE VARCHAR(1), BCOMP_SHARD_STRATEGY VARCHAR(20));
CREATE TABLE TSS_BCOMP_TASK_NEW (BCOMP_INDEX BIGINT, TASK_BUSI_DATE VARCHAR(8), TASK_BATCH VARCHAR(20), BCOMP_TIME_NODE VARCHAR(20), VERIFY_BUSINESS_DATE VARCHAR(8), CREATE_DATETIME VARCHAR(14), TASK_STATE VARCHAR(1), TASK_RESULT VARCHAR(1), BEGIN_DATETIME VARCHAR(14), END_DATETIME VARCHAR(14), FTASK_REASON VARCHAR(2000), FILE1_ACOUNT BIGINT, FILE2_ACOUNT BIGINT, FILE1_SCOUNT BIGINT, FILE2_SCOUNT BIGINT, FILE1_FCOUNT BIGINT, FILE2_FCOUNT BIGINT, BCOMP_READ_MODE VARCHAR(1000));
CREATE TABLE TSS_BCOMP_DATABASE_CONFIG_NEW (DATABASE_ID BIGINT PRIMARY KEY, DATABASE_NAME VARCHAR(100), DATABASE_URL VARCHAR(1000), DATABASE_USER VARCHAR(100), DATABASE_PASSWORD VARCHAR(1000), DATABASE_DRIVER VARCHAR(200), DATABASE_ENCRYPTION VARCHAR(1), DATABASE_GENERATERKEY VARCHAR(200));
CREATE TABLE TSS_BCOMP_TABLE_SQL_NEW (BCOMP_INDEX BIGINT, ORIG_DATABASE_ID BIGINT, DEST_DATABASE_ID BIGINT, ORIG_SQL VARCHAR(4000), DEST_SQL VARCHAR(4000));
CREATE TABLE TSS_BCOMP_FIELD_NEW (BCOMP_INDEX BIGINT, FIELD_NAME VARCHAR(100), FIELD_TYPE VARCHAR(1), FIELD_MEMO VARCHAR(500), FIELD_OLD_INDEX BIGINT, FIELD_NEW_INDEX BIGINT, FIELD_INDEX_FLAG VARCHAR(1), FIELD_ENUM_FLAG VARCHAR(1), FIELD_ENUM_INDEX BIGINT, FIELD_PARTITION_FLAG VARCHAR(1), FIELD_IGNORE_VALUE VARCHAR(100), FIELD_IGNORE_FLAG VARCHAR(1));
CREATE TABLE TSS_BCOMP_DTL_NEW (BCOMP_INDEX BIGINT, TASK_DATE VARCHAR(8), TASK_BATCH VARCHAR(20), COMP_INDEX_STR VARCHAR(1000), LINE_CONTENT1 VARCHAR(4000), LINE_CONTENT2 VARCHAR(4000), LINE_RESULT VARCHAR(1), FDTL_REASON VARCHAR(2000));
CREATE TABLE TSS_BCOMP_ENUM (CONV_ENUM_INDEX BIGINT, ORIG_ENUM_VALUE VARCHAR(200), DEST_ENUM_VALUE VARCHAR(200));
CREATE TABLE TSS_IGNORE_VALUE (IGNORE_ID BIGINT, IGNORE_VALUE VARCHAR(200));
